calls = 0

def fib(n):
    global calls
    calls += 1
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

from functools import lru_cache

@lru_cache(maxsize=None)
def fib_memo(n):
    if n < 2:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)

for n in (10, 20, 30):
    calls = 0
    value = fib(n)
    fib_memo.cache_clear()
    assert fib_memo(n) == value
    print(f"fib({n}) = {value:>6}   plain recursion made {calls:>9,} calls   memoised made {fib_memo.cache_info().misses} calls")

folder = {
    "notes.txt": 12,
    "photos": {"beach.jpg": 2400, "party.jpg": 1800, "old": {"2019.jpg": 900}},
    "school": {"maths.pdf": 350, "project": {"report.docx": 120, "data.csv": 40}},
