def total_size(item):
    if isinstance(item, int):                          # base case: a file has a size
        return item
    return sum(total_size(child) for child in item.values())   # a folder: add up its contents

def show(item, name="my folder", depth=0):
    print("    " * depth + f"{name}  ({total_size(item):,} KB)")
    if isinstance(item, dict):
        for child_name, child in item.items():
            show(child, child_name, depth + 1)

show(folder)
